const fs = require("fs");
const path = require("path");

function existe(caminho) {
  return fs.existsSync(caminho);
}

function copiarDiretorio(origem, destino) {
  if (!existe(origem)) return false;
  fs.mkdirSync(destino, { recursive: true });
  fs.cpSync(origem, destino, { recursive: true, force: true });
  return true;
}

function copiarArquivo(origem, destino) {
  if (!existe(origem)) return false;
  fs.mkdirSync(path.dirname(destino), { recursive: true });
  fs.copyFileSync(origem, destino);
  return true;
}

module.exports = async function afterPack(context) {
  const projeto = context.packager.projectDir;
  const appDir = path.join(context.appOutDir, "resources", "app");
  const standaloneDestino = path.join(appDir, ".next", "standalone");

  copiarDiretorio(path.join(projeto, ".next", "standalone"), standaloneDestino);
  copiarDiretorio(path.join(projeto, ".next", "static"), path.join(standaloneDestino, ".next", "static"));
  copiarDiretorio(path.join(projeto, "public"), path.join(standaloneDestino, "public"));

  const scriptsDestino = path.join(standaloneDestino, "scripts");
  [
    "backup-api.js",
    "backup-core.js",
    "backup-local.js",
    "restore-local.js",
    "backup-auto.js",
  ].forEach((nome) => {
    copiarArquivo(path.join(projeto, "scripts", nome), path.join(scriptsDestino, nome));
  });

  const server = path.join(standaloneDestino, "server.js");
  if (!existe(server)) {
    throw new Error(`Standalone do Next não foi copiado para o pacote: ${server}`);
  }
};

// scripts/preparar-standalone-desktop.js
// Nio-OS Desktop V11
// Prepara a pasta .next/standalone para o Electron Builder sem copiar dados reais para Program Files.

const fs = require("fs");
const path = require("path");

const raiz = process.cwd();

function normalizar(caminho) {
  return caminho.replace(/\\/g, "/");
}

function relativo(caminho) {
  return normalizar(path.relative(raiz, caminho));
}

function deveIgnorar(origem) {
  const rel = relativo(origem);

  return (
    rel === "data" ||
    rel.startsWith("data/") ||
    rel === "backups" ||
    rel.startsWith("backups/") ||
    rel === "storage" ||
    rel.startsWith("storage/") ||
    rel === "public/uploads" ||
    rel.startsWith("public/uploads/")
  );
}

function garantirPasta(destino) {
  fs.mkdirSync(destino, { recursive: true });
}

function remover(caminho) {
  if (fs.existsSync(caminho)) {
    fs.rmSync(caminho, { recursive: true, force: true });
  }
}

function copiar(origem, destino) {
  if (!fs.existsSync(origem)) return false;
  if (deveIgnorar(origem)) return false;

  const stat = fs.statSync(origem);

  if (stat.isDirectory()) {
    garantirPasta(destino);

    for (const item of fs.readdirSync(origem)) {
      copiar(path.join(origem, item), path.join(destino, item));
    }

    return true;
  }

  garantirPasta(path.dirname(destino));
  fs.copyFileSync(origem, destino);
  return true;
}

function copiarLimpando(origem, destino) {
  if (!fs.existsSync(origem)) return false;
  remover(destino);
  return copiar(origem, destino);
}

function main() {
  const standalone = path.join(raiz, ".next", "standalone");

  if (!fs.existsSync(standalone)) {
    console.error("ERRO: .next/standalone nao encontrado.");
    console.error('Verifique se next.config.ts possui output: "standalone" e rode npm run build.');
    process.exit(1);
  }

  copiarLimpando(
    path.join(raiz, ".next", "static"),
    path.join(standalone, ".next", "static")
  );

  copiarLimpando(
    path.join(raiz, "public"),
    path.join(standalone, "public")
  );

  copiarLimpando(
    path.join(raiz, "prisma"),
    path.join(standalone, "prisma")
  );

  copiarLimpando(
    path.join(raiz, "node_modules", ".prisma"),
    path.join(standalone, "node_modules", ".prisma")
  );

  copiarLimpando(
    path.join(raiz, "node_modules", "@prisma", "client"),
    path.join(standalone, "node_modules", "@prisma", "client")
  );

  console.log("====================================");
  console.log(" Standalone desktop V11 preparado.");
  console.log("====================================");
  console.log("Dados reais ficam fora de Program Files.");
}

main();

#!/usr/bin/env node
"use strict";

const fs = require("node:fs");
const path = require("node:path");
const { DatabaseSync } = require("node:sqlite");

const root = process.cwd();
const sourceFile = path.resolve(
  process.env.NIO_OS_SEED_SCHEMA_SOURCE ||
    path.join(root, "data", "nio-os.db"),
);
const seedDir = path.join(root, "build", "seed", "data");
const seedFile = path.join(seedDir, "nio-os.db");
const tempFile = path.join(
  seedDir,
  `.nio-os-seed-${process.pid}-${Date.now()}.tmp.db`,
);
const migrationManifestFile = path.join(
  root,
  "scripts",
  "schema-migrator",
  "migrations.cjs",
);

function cleanup(file) {
  for (const candidate of [
    file,
    `${file}-wal`,
    `${file}-shm`,
    `${file}-journal`,
  ]) {
    try {
      fs.rmSync(candidate, { force: true });
    } catch {}
  }
}

function safeIdent(value) {
  return String(value).replaceAll('"', '""');
}

function userTables(db) {
  return db
    .prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",
    )
    .all()
    .map((row) => String(row.name));
}

function schemaObjects(db) {
  return db
    .prepare(
      `SELECT type, name, tbl_name AS tableName, sql
       FROM sqlite_master
       WHERE name NOT LIKE 'sqlite_%'
         AND sql IS NOT NULL
         AND type IN ('table','index','trigger','view')
       ORDER BY
         CASE type
           WHEN 'table' THEN 1
           WHEN 'index' THEN 2
           WHEN 'trigger' THEN 3
           WHEN 'view' THEN 4
           ELSE 9
         END,
         name`,
    )
    .all()
    .map((row) => ({
      type: String(row.type),
      name: String(row.name),
      tableName: String(row.tableName),
      sql: String(row.sql),
    }));
}

function health(db, label) {
  const integrity = db.prepare("PRAGMA integrity_check").all();
  const foreignKeys = db.prepare("PRAGMA foreign_key_check").all();

  if (
    integrity.length !== 1 ||
    String(integrity[0].integrity_check) !== "ok"
  ) {
    throw new Error(`${label}: integrity_check não retornou ok.`);
  }

  if (foreignKeys.length !== 0) {
    throw new Error(`${label}: existem violações de chave estrangeira.`);
  }

  return {
    integrityCheck: "ok",
    foreignKeyViolations: 0,
  };
}

function migrationRows(db) {
  if (!userTables(db).includes("NioSchemaMigration")) {
    throw new Error("Banco fonte não possui NioSchemaMigration.");
  }

  return db
    .prepare('SELECT * FROM "NioSchemaMigration" ORDER BY rowid')
    .all();
}

function validateMigrationHistory(sourceRows) {
  if (!fs.existsSync(migrationManifestFile)) {
    throw new Error(
      `Manifesto do migrador não encontrado: ${migrationManifestFile}`,
    );
  }

  const manifest = require(migrationManifestFile);
  const migrations = Array.isArray(manifest?.migrations)
    ? manifest.migrations
    : [];

  if (migrations.length === 0) {
    throw new Error("Manifesto do migrador não possui migrações.");
  }

  if (sourceRows.length !== migrations.length) {
    throw new Error(
      `Banco fonte não está no schema atual: ${sourceRows.length} migrações aplicadas, ${migrations.length} esperadas.`,
    );
  }

  for (let index = 0; index < migrations.length; index += 1) {
    const expected = migrations[index];
    const actual = sourceRows[index];

    if (String(actual.id) !== String(expected.id)) {
      throw new Error(
        `Histórico de migração fora de ordem na posição ${index + 1}.`,
      );
    }

    if (String(actual.checksum) !== String(expected.checksum)) {
      throw new Error(
        `Checksum de migração divergente: ${String(expected.id)}.`,
      );
    }
  }

  return migrations.length;
}

function insertMigrationRows(target, rows) {
  if (rows.length === 0) return;

  const targetColumns = new Set(
    target
      .prepare('PRAGMA table_info("NioSchemaMigration")')
      .all()
      .map((row) => String(row.name)),
  );

  const sourceColumns = Object.keys(rows[0]).filter((column) =>
    targetColumns.has(column),
  );

  if (!sourceColumns.includes("id") || !sourceColumns.includes("checksum")) {
    throw new Error(
      "Tabela NioSchemaMigration incompatível para criação do seed.",
    );
  }

  const sql =
    `INSERT INTO "NioSchemaMigration" (` +
    sourceColumns.map((column) => `"${safeIdent(column)}"`).join(", ") +
    `) VALUES (` +
    sourceColumns.map(() => "?").join(", ") +
    `)`;

  const statement = target.prepare(sql);

  for (const row of rows) {
    statement.run(...sourceColumns.map((column) => row[column]));
  }
}

function validateNoBusinessRows(db) {
  const nonEmpty = [];

  for (const table of userTables(db)) {
    if (table === "NioSchemaMigration") continue;

    const count = Number(
      db
        .prepare(
          `SELECT COUNT(*) AS c FROM "${safeIdent(table)}"`,
        )
        .get().c,
    );

    if (count !== 0) {
      nonEmpty.push({ table, count });
    }
  }

  if (nonEmpty.length > 0) {
    throw new Error(
      `Seed recusado: existem dados de negócio: ${JSON.stringify(nonEmpty)}`,
    );
  }
}

function normalizeSql(sql) {
  return String(sql || "")
    .replace(/\s+/g, " ")
    .trim();
}

function validateSchemaEquivalent(sourceObjects, seedDb) {
  const seedObjects = schemaObjects(seedDb);

  if (seedObjects.length !== sourceObjects.length) {
    throw new Error(
      `Seed recusado: quantidade de objetos de schema divergiu (${seedObjects.length}/${sourceObjects.length}).`,
    );
  }

  for (let index = 0; index < sourceObjects.length; index += 1) {
    const source = sourceObjects[index];
    const seed = seedObjects[index];

    if (
      source.type !== seed.type ||
      source.name !== seed.name ||
      source.tableName !== seed.tableName ||
      normalizeSql(source.sql) !== normalizeSql(seed.sql)
    ) {
      throw new Error(
        `Seed recusado: objeto de schema divergente em ${source.type}:${source.name}.`,
      );
    }
  }
}

function main() {
  if (!fs.existsSync(sourceFile)) {
    throw new Error(`Banco fonte de schema não encontrado: ${sourceFile}`);
  }

  if (
    fs.existsSync(`${sourceFile}-wal`) ||
    fs.existsSync(`${sourceFile}-shm`)
  ) {
    throw new Error(
      "Banco fonte possui WAL/SHM. Feche completamente o Nio-OS antes de gerar o seed.",
    );
  }

  fs.mkdirSync(seedDir, { recursive: true });
  cleanup(tempFile);

  const source = new DatabaseSync(sourceFile, { readOnly: true });
  let sourceObjects;
  let sourceMigrations;
  let migrationCount;

  try {
    health(source, "Banco fonte");
    sourceObjects = schemaObjects(source);
    sourceMigrations = migrationRows(source);
    migrationCount = validateMigrationHistory(sourceMigrations);
  } finally {
    source.close();
  }

  if (sourceObjects.length === 0) {
    throw new Error("Banco fonte não possui objetos de schema reconhecidos.");
  }

  const seed = new DatabaseSync(tempFile);

  try {
    seed.exec("PRAGMA foreign_keys = OFF");
    seed.exec("BEGIN IMMEDIATE");

    try {
      for (const object of sourceObjects) {
        seed.exec(object.sql);
      }

      insertMigrationRows(seed, sourceMigrations);
      seed.exec("COMMIT");
    } catch (error) {
      try {
        seed.exec("ROLLBACK");
      } catch {}
      throw error;
    }

    seed.exec("PRAGMA foreign_keys = ON");
    validateNoBusinessRows(seed);
    validateSchemaEquivalent(sourceObjects, seed);
    health(seed, "Seed");
  } finally {
    seed.close();
  }

  cleanup(seedFile);
  fs.renameSync(tempFile, seedFile);

  const finalSeed = new DatabaseSync(seedFile, { readOnly: true });

  try {
    const finalHealth = health(finalSeed, "Seed final");
    validateNoBusinessRows(finalSeed);
    validateSchemaEquivalent(sourceObjects, finalSeed);

    console.log(
      JSON.stringify({
        ok: true,
        stage: "4A.7B-SEED-SQLITE",
        seed: path
          .relative(root, seedFile)
          .replaceAll(path.sep, "/"),
        sizeBytes: fs.statSync(seedFile).size,
        tableCount: userTables(finalSeed).length,
        schemaObjectCount: sourceObjects.length,
        migrationCount,
        businessRows: 0,
        integrityCheck: finalHealth.integrityCheck,
        foreignKeyViolations:
          finalHealth.foreignKeyViolations,
        sourceSchemaRead: true,
        sourceMigrationHistoryRead: true,
        sourceBusinessRowsRead: false,
        sourceBusinessDatabaseCopied: false,
        prismaDbPushUsed: false,
        schemaMigratorBootstrapUsed: false,
        liveDatabaseChanged: false,
        promotionPerformed: false,
      }),
    );
  } finally {
    finalSeed.close();
  }
}

try {
  main();
} catch (error) {
  cleanup(tempFile);

  console.error(
    JSON.stringify({
      ok: false,
      stage: "4A.7B-SEED-SQLITE",
      message:
        error instanceof Error ? error.message : String(error),
      sourceSchemaRead: true,
      sourceBusinessRowsRead: false,
      sourceBusinessDatabaseCopied: false,
      prismaDbPushUsed: false,
      liveDatabaseChanged: false,
      promotionPerformed: false,
    }),
  );

  process.exit(1);
}

// desktop/main.cjs
// Nio-OS Desktop V11
// - Janela propria Electron.
// - Modo servidor/cliente salvo.
// - PDFs/recibos/rotas internas dentro do Electron.
// - Build empacotado via Next standalone + electron-builder.
// - Dados reais em %LOCALAPPDATA%\Nio-OS, fora de Program Files.

const { app, BrowserWindow, ipcMain, shell, Menu, dialog } = require("electron");
const path = require("path");
const fs = require("fs");
const os = require("os");
const crypto = require("crypto");
const { spawn } = require("child_process");

const APP_NAME = "Nio-OS | Ordem de Serviço";
const PORTA = Number(process.env.PORT || 3000);
const LOCAL_ORIGIN = `http://127.0.0.1:${PORTA}`;
const PROJECT_ROOT = path.resolve(__dirname, "..");
const SELECTOR_HTML = path.join(__dirname, "seletor.html");
const PRELOAD = path.join(__dirname, "preload.cjs");

let mainWindow = null;
let serverProcess = null;
let iniciandoServidor = false;
let servidorAtual = LOCAL_ORIGIN;
let autoIniciado = false;
const instanceLock = app.requestSingleInstanceLock();

if (!instanceLock) {
  app.quit();
}

const internalOrigins = new Set([
  `http://127.0.0.1:${PORTA}`,
  `http://localhost:${PORTA}`,
  `http://0.0.0.0:${PORTA}`,
]);

try {
  app.setName("Nio-OS");

  if (process.platform === "win32") {
    app.setPath("userData", path.join(process.env.LOCALAPPDATA || app.getPath("appData"), "Nio-OS"));
  }
} catch (error) {
  console.error("Nao foi possivel definir userData do Nio-OS:", error);
}

function appDataPath(...partes) {
  return path.join(app.getPath("userData"), ...partes);
}

function caminhoRaizRoamingLegada() {
  if (process.platform !== "win32" || !process.env.APPDATA) return "";
  return path.join(process.env.APPDATA, "Nio-OS");
}

function caminhoRoamingLegado(...partes) {
  const raiz = caminhoRaizRoamingLegada();
  return raiz ? path.join(raiz, ...partes) : "";
}

function configPath() {
  return appDataPath("nio-os-desktop-config.json");
}

function logPath() {
  return appDataPath("nio-os-desktop.log");
}

function log(...partes) {
  const linha = `[${new Date().toISOString()}] ${partes
    .map((parte) =>
      typeof parte === "string" ? parte : JSON.stringify(parte, null, 2)
    )
    .join(" ")}\n`;

  try {
    fs.mkdirSync(path.dirname(logPath()), { recursive: true });
    fs.appendFileSync(logPath(), linha, "utf8");
  } catch {}

  console.log(...partes);
}

function lerConfig() {
  try {
    const arquivo = configPath();
    if (!fs.existsSync(arquivo)) return {};
    return JSON.parse(fs.readFileSync(arquivo, "utf8"));
  } catch {
    return {};
  }
}

function salvarConfig(parcial) {
  const atual = lerConfig();
  const novo = {
    ...atual,
    ...parcial,
    updatedAt: new Date().toISOString(),
  };

  try {
    fs.mkdirSync(path.dirname(configPath()), { recursive: true });
    fs.writeFileSync(configPath(), JSON.stringify(novo, null, 2), "utf8");
  } catch (error) {
    log("Erro ao salvar configuracao:", String(error));
  }

  return novo;
}

function obterAuthSecretLocal() {
  const atual = lerConfig();

  if (atual.authSecret && String(atual.authSecret).length >= 32) {
    return String(atual.authSecret);
  }

  const secret = crypto.randomBytes(48).toString("hex");
  salvarConfig({ authSecret: secret });
  return secret;
}

function limparModoSalvo() {
  salvarConfig({
    lastMode: "",
    lastServerUrl: "",
    autoStart: false,
  });
}

function enviarStatus(mensagem, tipo = "") {
  log(mensagem);

  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send("nio-os:status", { mensagem, tipo });
  }
}

function normalizarUrlServidor(valor) {
  const texto = String(valor || "").trim();

  if (!texto) return "";

  if (texto.startsWith("http://") || texto.startsWith("https://")) {
    return texto.replace(/\/+$/, "");
  }

  return `http://${texto.replace(/\/+$/, "")}`;
}

function adicionarOrigemInterna(url) {
  try {
    const origem = new URL(url).origin;
    internalOrigins.add(origem);
    servidorAtual = origem;
  } catch {}
}

function urlInterna(url) {
  try {
    const destino = new URL(url);
    return internalOrigins.has(destino.origin);
  } catch {
    return false;
  }
}

function abrirUrlExternaSegura(url) {
  const destino = String(url || "");

  if (!destino || destino.startsWith("about:")) return;

  shell.openExternal(destino).catch((error) => {
    log("Erro ao abrir link externo:", destino, String(error));
  });
}

function configurarJanelaDocumento(janela) {
  janela.setMenuBarVisibility(false);

  janela.webContents.setWindowOpenHandler((details) => {
    const destino = String(details?.url || "");

    if (!destino || destino === "about:blank" || destino.startsWith("about:")) {
      return {
        action: "allow",
        overrideBrowserWindowOptions: {
          title: "Nio-OS | Documento",
          width: 980,
          height: 760,
          autoHideMenuBar: true,
          backgroundColor: "#ffffff",
          webPreferences: {
            contextIsolation: true,
            nodeIntegration: false,
            sandbox: true,
          },
        },
      };
    }

    if (urlInterna(destino)) {
      criarJanelaInterna(destino, "Nio-OS | Documento");
      return { action: "deny" };
    }

    abrirUrlExternaSegura(destino);
    return { action: "deny" };
  });

  janela.webContents.on("will-navigate", (event, destino) => {
    if (urlInterna(destino)) return;

    event.preventDefault();
    abrirUrlExternaSegura(destino);
  });

  janela.webContents.setVisualZoomLevelLimits(1, 1).catch(() => {});
}

function criarJanelaInterna(url, titulo = "Nio-OS | Documento") {
  adicionarOrigemInterna(url);

  const janela = new BrowserWindow({
    title: titulo,
    width: 1100,
    height: 800,
    minWidth: 900,
    minHeight: 650,
    autoHideMenuBar: true,
    backgroundColor: "#f8fafc",
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
      webSecurity: true,
    },
  });

  configurarJanelaDocumento(janela);
  janela.loadURL(url);
  return janela;
}

function configurarJanelaPrincipal(win) {
  win.webContents.setWindowOpenHandler((details) => {
    const destino = String(details?.url || "");

    if (!destino || destino === "about:blank" || destino.startsWith("about:")) {
      return {
        action: "allow",
        overrideBrowserWindowOptions: {
          title: "Nio-OS | Documento",
          width: 980,
          height: 760,
          autoHideMenuBar: true,
          backgroundColor: "#ffffff",
          webPreferences: {
            contextIsolation: true,
            nodeIntegration: false,
            sandbox: true,
          },
        },
      };
    }

    if (urlInterna(destino)) {
      criarJanelaInterna(destino, "Nio-OS | Documento");
      return { action: "deny" };
    }

    abrirUrlExternaSegura(destino);
    return { action: "deny" };
  });

  win.webContents.on("will-navigate", (event, destino) => {
    if (urlInterna(destino)) return;

    event.preventDefault();
    abrirUrlExternaSegura(destino);
  });

  win.webContents.on("before-input-event", (event, input) => {
    const ctrl = input.control || input.meta;

    if (ctrl && ["+", "-", "=", "0"].includes(input.key)) {
      event.preventDefault();
    }

    if (input.key === "F11") {
      event.preventDefault();
    }
  });

  win.webContents.setVisualZoomLevelLimits(1, 1).catch(() => {});
}

function criarJanelaPrincipal() {
  Menu.setApplicationMenu(null);

  mainWindow = new BrowserWindow({
    width: 1280,
    height: 820,
    minWidth: 1024,
    minHeight: 700,
    title: APP_NAME,
    show: false,
    autoHideMenuBar: true,
    backgroundColor: "#0f172a",
    webPreferences: {
      preload: PRELOAD,
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
      webSecurity: true,
    },
  });

  mainWindow.setMenuBarVisibility(false);
  mainWindow.maximize();
  configurarJanelaPrincipal(mainWindow);

  mainWindow.once("ready-to-show", () => {
    mainWindow.show();
  });

  mainWindow.loadFile(SELECTOR_HTML);

  mainWindow.webContents.once("did-finish-load", () => {
    tentarAutoIniciar();
  });

  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

async function tentarAutoIniciar() {
  if (autoIniciado) return;
  autoIniciado = true;

  const config = lerConfig();

  if (config.autoStart === false) return;

  if (config.lastMode === "server") {
    enviarStatus("Abrindo automaticamente como servidor...", "info");
    await iniciarServidor({ salvarModo: false });
    return;
  }

  if (config.lastMode === "client" && config.lastServerUrl) {
    enviarStatus("Conectando automaticamente ao ultimo servidor...", "info");
    await iniciarCliente(config.lastServerUrl, { salvarModo: false });
  }
}

function caminhoSqliteLocal() {
  if (app.isPackaged) {
    return appDataPath("data", "nio-os.db");
  }

  return path.join(PROJECT_ROOT, "data", "nio-os.db");
}

function normalizarPathSQLite(caminho) {
  return caminho.replace(/\\/g, "/");
}

function databaseUrlLocal() {
  return `file:${normalizarPathSQLite(caminhoSqliteLocal())}`;
}

function copiarSeNaoExistir(origem, destino) {
  if (!origem || !destino) return false;
  if (!fs.existsSync(origem) || fs.existsSync(destino)) return false;

  fs.mkdirSync(path.dirname(destino), { recursive: true });
  fs.copyFileSync(origem, destino);
  return true;
}

function copiarBancoComAuxiliares(origem, destino) {
  const ok = copiarSeNaoExistir(origem, destino);

  if (ok) {
    for (const sufixo of ["-wal", "-shm"]) {
      copiarSeNaoExistir(`${origem}${sufixo}`, `${destino}${sufixo}`);
    }
  }

  return ok;
}

function pastaVazia(caminho) {
  if (!fs.existsSync(caminho)) return true;

  try {
    return fs.readdirSync(caminho).length === 0;
  } catch {
    return true;
  }
}

function copiarPastaSeDestinoVazio(origem, destino) {
  if (!origem || !destino) return false;
  if (!fs.existsSync(origem) || !pastaVazia(destino)) return false;

  fs.mkdirSync(path.dirname(destino), { recursive: true });
  fs.cpSync(origem, destino, { recursive: true, force: true });
  return true;
}

function migrarDadosRoamingLegados() {
  if (!app.isPackaged) return;

  const raizLegada = caminhoRaizRoamingLegada();
  const raizAtual = app.getPath("userData");

  if (
    !raizLegada ||
    path.resolve(raizLegada) === path.resolve(raizAtual) ||
    !fs.existsSync(raizLegada)
  ) {
    return;
  }

  copiarSeNaoExistir(
    caminhoRoamingLegado("nio-os-desktop-config.json"),
    configPath()
  );

  copiarBancoComAuxiliares(
    caminhoRoamingLegado("data", "nio-os.db"),
    caminhoSqliteLocal()
  );

  copiarPastaSeDestinoVazio(
    caminhoRoamingLegado("public", "uploads"),
    appDataPath("public", "uploads")
  );

  copiarPastaSeDestinoVazio(
    caminhoRoamingLegado("storage"),
    appDataPath("storage")
  );

  copiarPastaSeDestinoVazio(
    caminhoRoamingLegado("backups"),
    appDataPath("backups")
  );
}

function caminhoBancoLegadoInstalado() {
  return path.join(PROJECT_ROOT, "data", "nio-os.db");
}

function caminhoBancoSeed() {
  if (app.isPackaged) {
    return path.join(process.resourcesPath, "seed", "data", "nio-os.db");
  }

  return path.join(PROJECT_ROOT, "data", "nio-os.db");
}

function escreverEnvRuntime() {
  const envPath = appDataPath(".env");
  const linhas = [
    `DATABASE_URL="${databaseUrlLocal()}"`,
    `NODE_ENV="production"`,
    `PORT="${PORTA}"`,
    `HOST="0.0.0.0"`,
    `HOSTNAME="0.0.0.0"`,
    `COOKIE_SECURE="false"`,
    `NEXT_TELEMETRY_DISABLED="1"`,
    `NIO_OS_DATA_DIR="${normalizarPathSQLite(app.getPath("userData"))}"`,
    `NIO_OS_RUNTIME_DIR="${normalizarPathSQLite(app.getPath("userData"))}"`,
    `AUTH_SECRET="${obterAuthSecretLocal()}"`,
    "",
  ];

  fs.mkdirSync(path.dirname(envPath), { recursive: true });
  fs.writeFileSync(envPath, linhas.join("\r\n"), "utf8");
  return envPath;
}

function prepararPastasLocais() {
  migrarDadosRoamingLegados();

  const pastas = [
    appDataPath("data"),
    appDataPath("backups"),
    appDataPath("public", "uploads"),
    appDataPath("storage", "uploads", "anexos"),
  ];

  for (const pasta of pastas) {
    fs.mkdirSync(pasta, { recursive: true });
  }

  if (app.isPackaged) {
    const bancoDestino = caminhoSqliteLocal();
    const fontesBanco = [
      caminhoBancoLegadoInstalado(),
      caminhoBancoSeed(),
    ];

    for (const fonte of fontesBanco) {
      if (fs.existsSync(bancoDestino)) break;

      if (copiarBancoComAuxiliares(fonte, bancoDestino)) {
        log("Banco SQLite inicial/migrado para LOCALAPPDATA:", bancoDestino, "origem:", fonte);
        break;
      }
    }

    copiarPastaSeDestinoVazio(
      path.join(PROJECT_ROOT, "public", "uploads"),
      appDataPath("public", "uploads")
    );

    copiarPastaSeDestinoVazio(
      path.join(PROJECT_ROOT, "storage"),
      appDataPath("storage")
    );
  }

  const envPath = escreverEnvRuntime();
  log("Pasta de dados Nio-OS:", app.getPath("userData"));
  log("DATABASE_URL em uso:", databaseUrlLocal());
  log("Env runtime:", envPath);
}

function pastaBackupsSchema() {
  return appDataPath("backups", "schema");
}

function caminhoConfinadoAoAppData(caminho) {
  const raiz = path.resolve(app.getPath("userData"));
  const destino = path.resolve(caminho);
  const relativo = path.relative(raiz, destino);
  return relativo !== "" && !relativo.startsWith("..") && !path.isAbsolute(relativo);
}

async function mostrarFalhaMigracao(resultado) {
  const backupDir = pastaBackupsSchema();
  const detalhes = [
    `Código técnico: ${resultado.code || "MIGRATION_PROCESS_ERROR"}`,
    "Nenhum dado foi apagado.",
    `Backups de schema: ${backupDir}`,
    "Contate o suporte e informe o código técnico.",
  ].join("\n");
  const escolha = await dialog.showMessageBox({
    type: "error",
    title: "Falha ao preparar o banco de dados",
    message: "O Nio-OS não iniciou para proteger seus dados.",
    detail: detalhes,
    buttons: ["Fechar o Nio-OS", "Abrir pasta de backups"],
    defaultId: 0,
    cancelId: 0,
    noLink: true,
  });

  if (escolha.response === 1 && caminhoConfinadoAoAppData(backupDir)) {
    fs.mkdirSync(backupDir, { recursive: true });
    const erro = await shell.openPath(backupDir);
    if (erro) log("Falha ao abrir pasta de backups de schema:", erro);
  }
}

async function executarMigradorSchema() {
  const databasePath = caminhoSqliteLocal();
  const backupDir = pastaBackupsSchema();
  if (!path.isAbsolute(databasePath) || !fs.existsSync(databasePath)) {
    return {
      ok: false,
      code: "MIGRATION_DATABASE_NOT_FOUND",
      database: path.basename(databasePath),
      backupPath: null,
      durationMs: 0,
      message: "Banco runtime não foi localizado após a preparação.",
    };
  }

  const { runSchemaMigrator } = require("./schemaMigratorRunner.cjs");
  return runSchemaMigrator({
    appPath: app.getAppPath(),
    resourcesPath: process.resourcesPath,
    databasePath,
    backupDir,
    executablePath: process.execPath,
  });
}

function caminhoServidorStandalone() {
  return path.join(PROJECT_ROOT, ".next", "standalone", "server.js");
}

function comandoStartServidor() {
  if (app.isPackaged) {
    const serverJs = caminhoServidorStandalone();

    if (!fs.existsSync(serverJs)) {
      throw new Error(
        `Servidor empacotado nao encontrado: ${serverJs}. Rode o build do instalador novamente.`
      );
    }

    return {
      comando: process.execPath,
      args: [serverJs],
      cwd: path.dirname(serverJs),
      envExtra: {
        ELECTRON_RUN_AS_NODE: "1",
      },
    };
  }

  return {
    comando: "cmd.exe",
    args: ["/d", "/s", "/c", `npm run start -- -H 0.0.0.0 -p ${PORTA}`],
    cwd: PROJECT_ROOT,
    envExtra: {},
  };
}

function iniciarProcessoServidor() {
  const { comando, args, cwd, envExtra } = comandoStartServidor();

  enviarStatus(`Iniciando servidor local em ${LOCAL_ORIGIN}...`, "info");
  log("Iniciando servidor:", comando, args.join(" "), "cwd:", cwd);

  serverProcess = spawn(comando, args, {
    cwd,
    env: {
      ...process.env,
      ...envExtra,
      NODE_ENV: "production",
      HOST: "0.0.0.0",
      HOSTNAME: "0.0.0.0",
      PORT: String(PORTA),
      COOKIE_SECURE: "false",
      NEXT_TELEMETRY_DISABLED: "1",
      DATABASE_URL: databaseUrlLocal(),
      AUTH_SECRET: process.env.AUTH_SECRET || obterAuthSecretLocal(),
      NIO_OS_DATA_DIR: app.getPath("userData"),
      NIO_OS_RUNTIME_DIR: app.getPath("userData"),
      NIO_OS_ENV_PATH: appDataPath(".env"),
    },
    windowsHide: true,
    stdio: ["ignore", "pipe", "pipe"],
  });

  serverProcess.stdout.on("data", (data) => {
    log("[next]", data.toString().trim());
  });

  serverProcess.stderr.on("data", (data) => {
    log("[next:erro]", data.toString().trim());
  });

  serverProcess.on("exit", (code, signal) => {
    log("Servidor encerrado:", { code, signal });
    serverProcess = null;
  });

  serverProcess.on("error", (error) => {
    log("Erro ao iniciar processo servidor:", String(error));
  });
}

async function testarUrl(url, timeoutMs = 1200) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      method: "GET",
      cache: "no-store",
      signal: controller.signal,
    });

    clearTimeout(timeout);

    return {
      ok: response.status >= 200 && response.status < 500,
      status: response.status,
    };
  } catch (error) {
    clearTimeout(timeout);
    return {
      ok: false,
      status: 0,
      error: error?.message || String(error),
    };
  }
}

async function servidorRespondendo(baseUrl) {
  const base = normalizarUrlServidor(baseUrl) || LOCAL_ORIGIN;
  const rotas = [
    "/api/local/health",
    "/api/auth/setup",
    "/login",
    "/",
  ];

  for (const rota of rotas) {
    const url = `${base}${rota}`;
    const resultado = await testarUrl(url);

    if (resultado.ok) {
      log("Detector servidor:", url, resultado);
      return true;
    }

    log("Detector falhou:", url, resultado);
  }

  return false;
}

async function esperarServidor(baseUrl, tentativas = 90) {
  const base = normalizarUrlServidor(baseUrl) || LOCAL_ORIGIN;

  for (let i = 1; i <= tentativas; i++) {
    enviarStatus(`Iniciando servidor local... Tentativa ${i}/${tentativas}`, "info");

    if (await servidorRespondendo(base)) {
      return true;
    }

    await new Promise((resolve) => setTimeout(resolve, 650));
  }

  return false;
}

async function carregarSistema(baseUrl) {
  const base = normalizarUrlServidor(baseUrl) || LOCAL_ORIGIN;
  adicionarOrigemInterna(base);

  if (!mainWindow || mainWindow.isDestroyed()) {
    criarJanelaPrincipal();
  }

  mainWindow.setTitle(APP_NAME);
  mainWindow.loadURL(`${base}/`);
  enviarStatus(`Conectado em ${base}`, "sucesso");
}

async function iniciarServidor(opcoes = {}) {
  if (iniciandoServidor) {
    return { ok: false, message: "Inicialização do servidor já está em andamento." };
  }
  iniciandoServidor = true;

  if (opcoes.salvarModo !== false) {
    salvarConfig({
      lastMode: "server",
      lastServerUrl: LOCAL_ORIGIN,
      autoStart: true,
    });
  }

  try {
    prepararPastasLocais();
    const resultadoMigracao = await executarMigradorSchema();
    log("Migrador de schema finalizado:", {
      code: resultadoMigracao.code,
      migrationId: resultadoMigracao.migrationId || null,
      database: resultadoMigracao.database,
      backupPath: resultadoMigracao.backupPath || null,
      durationMs: resultadoMigracao.durationMs,
      message: resultadoMigracao.ok ? undefined : resultadoMigracao.message,
    });
    if (!resultadoMigracao.ok) {
      await mostrarFalhaMigracao(resultadoMigracao);
      app.quit();
      return {
        ok: false,
        message: "Falha ao preparar o banco de dados.",
        code: resultadoMigracao.code,
      };
    }

    adicionarOrigemInterna(LOCAL_ORIGIN);
    if (await servidorRespondendo(LOCAL_ORIGIN)) {
      await carregarSistema(LOCAL_ORIGIN);
      return { ok: true };
    }

    if (!serverProcess) iniciarProcessoServidor();
    const ok = await esperarServidor(LOCAL_ORIGIN);
    if (!ok) {
      const message =
        `Servidor nao respondeu em ${LOCAL_ORIGIN}. ` +
        `Verifique se a porta ${PORTA} esta livre.`;
      enviarStatus(message, "erro");
      return { ok: false, message };
    }

    await carregarSistema(LOCAL_ORIGIN);
    return { ok: true };
  } finally {
    iniciandoServidor = false;
  }
}

function redesLocais() {
  const interfaces = os.networkInterfaces();
  const prefixes = new Set();

  for (const itens of Object.values(interfaces)) {
    for (const item of itens || []) {
      if (item.family !== "IPv4" || item.internal) continue;

      const partes = item.address.split(".");
      if (partes.length !== 4) continue;

      prefixes.add(`${partes[0]}.${partes[1]}.${partes[2]}`);
    }
  }

  return Array.from(prefixes);
}

async function encontrarServidorNaRede() {
  const candidatos = [];
  const config = lerConfig();

  if (config.lastServerUrl) {
    candidatos.push(normalizarUrlServidor(config.lastServerUrl));
  }

  for (const prefix of redesLocais()) {
    for (let i = 1; i <= 254; i++) {
      candidatos.push(`http://${prefix}.${i}:${PORTA}`);
    }
  }

  const unicos = Array.from(new Set(candidatos.filter(Boolean)));
  const concorrencia = 32;
  let indice = 0;

  async function worker() {
    while (indice < unicos.length) {
      const atual = unicos[indice++];
      enviarStatus(`Procurando servidor na rede...\n${atual}`, "info");

      if (await servidorRespondendo(atual)) {
        return atual;
      }
    }

    return "";
  }

  const workers = Array.from(
    { length: Math.min(concorrencia, unicos.length) },
    () => worker()
  );

  const resultado = await Promise.any(
    workers.map(async (item) => {
      const url = await item;
      if (!url) throw new Error("Nao encontrado");
      return url;
    })
  ).catch(() => "");

  return resultado;
}

async function iniciarCliente(urlManual = "", opcoes = {}) {
  let servidor = normalizarUrlServidor(urlManual);

  if (!servidor) {
    servidor = await encontrarServidorNaRede();
  }

  if (!servidor) {
    const message =
      "Servidor nao encontrado na rede. Confirme se o computador servidor esta aberto e na mesma rede Wi-Fi.";
    enviarStatus(message, "erro");
    return { ok: false, message };
  }

  if (!(await servidorRespondendo(servidor))) {
    const message = `Servidor nao respondeu em ${servidor}.`;
    enviarStatus(message, "erro");
    return { ok: false, message };
  }

  if (opcoes.salvarModo !== false) {
    salvarConfig({
      lastMode: "client",
      lastServerUrl: servidor,
      autoStart: true,
    });
  }

  await carregarSistema(servidor);
  return { ok: true };
}

